from register import Entry


def order_count(entries: list[Entry]) -> int:
    return sum(1 for entry in entries if entry.begins_run)


def run_count(entries: list[Entry]) -> int:
    return sum(entry.begins_run for entry in entries)


def tickets_in_order(entries: list[Entry]) -> list[int]:
    return [entry.notice["ticket"] for entry in entries]

