from register import Entry


def booked_units(entries: list[Entry]) -> int:
    return sum(entry.notice["units"] for entry in entries if entry.begins_run)


def largest_notice(entries: list[Entry]) -> int:
    return max((entry.notice["units"] for entry in entries), default=0)

