from activity import order_count, run_count
from quantities import booked_units
from register import register


def summarize(notices):
    entries = register(notices)
    return {"runs": run_count(entries), "orders": order_count(entries), "units": booked_units(entries)}


def main(batches):
    return [summarize(batch) for batch in batches]
